with ranked as (select * from (select *, row_number() over (partition by customer_id order by shipping_fee desc nulls last, id) as dedup_rank from orders) ranked where dedup_rank = 1) select case when discount >= 0.39 then 'LARGE' else 'SMALL' end as discount_tier, round(sum(shipping_fee) / nullif(count(case when channel = 'store' then 1 end), 0), 2) as shipping_fee_per_store, max(shipping_fee) filter (where status = 'COMPLETED') as completed_max_shipping_fee from ranked group by 1 order by discount_tier desc;
